using System.Net;using System.Text.Json;using HelpDesk.Api.Application.Authorization;using HelpDesk.Api.Application.Common.Exceptions;using HelpDesk.Api.Application.Tickets;using HelpDesk.Api.Contracts.Ai;using Moq;
namespace HelpDesk.Api.Tests;
public sealed class AiTicketEndpointIntegrationTests
{[Fact]public async Task AnonymousIsRejected(){await using var f=new AuthApiFactory();Assert.Equal(HttpStatusCode.Unauthorized,(await f.CreateClient().PostAsync($"/api/tickets/{AuthApiFactory.TicketId}/ai-analysis",null)).StatusCode);}
[Theory][InlineData(AppRoles.Admin)][InlineData(AppRoles.ItSupportAgent)][InlineData(AppRoles.Employee)][InlineData(AppRoles.Manager)]public async Task JwtIdentityAndRoleAreAuthoritative(string role){await using var f=new AuthApiFactory();var user=Guid.NewGuid();var client=f.CreateAuthorizedClient(user,role);client.DefaultRequestHeaders.Add("X-Role",AppRoles.Admin);client.DefaultRequestHeaders.Add("X-User-Id",Guid.NewGuid().ToString());var response=await client.PostAsync($"/api/tickets/{AuthApiFactory.TicketId}/ai-analysis?userId={Guid.NewGuid()}",new StringContent("{\"title\":\"override\"}",System.Text.Encoding.UTF8,"application/json"));Assert.Equal(HttpStatusCode.OK,response.StatusCode);f.AiTicketAnalysisService.Verify(x=>x.AnalyzeTicketAsync(AuthApiFactory.TicketId,It.Is<TicketAccessContext>(a=>a.UserId==user&&a.Roles.SequenceEqual(new[]{role})),It.IsAny<CancellationToken>()));}
[Fact]public async Task ResponseIsSafeContract(){await using var f=new AuthApiFactory();var response=await f.CreateAuthorizedClient(Guid.NewGuid(),AppRoles.Employee).PostAsync($"/api/tickets/{AuthApiFactory.TicketId}/ai-analysis",null);var text=await response.Content.ReadAsStringAsync();Assert.DoesNotContain("email",text,StringComparison.OrdinalIgnoreCase);Assert.DoesNotContain("apiKey",text,StringComparison.OrdinalIgnoreCase);Assert.DoesNotContain("token",text,StringComparison.OrdinalIgnoreCase);}
[Fact]public async Task UnavailableMapsToSafe503(){await using var f=new AuthApiFactory();f.AiTicketAnalysisService.Setup(x=>x.AnalyzeTicketAsync(It.IsAny<Guid>(),It.IsAny<TicketAccessContext>(),It.IsAny<CancellationToken>())).ThrowsAsync(new AiServiceUnavailableException());var response=await f.CreateAuthorizedClient(Guid.NewGuid(),AppRoles.Admin).PostAsync($"/api/tickets/{AuthApiFactory.TicketId}/ai-analysis",null);Assert.Equal(HttpStatusCode.ServiceUnavailable,response.StatusCode);var text=await response.Content.ReadAsStringAsync();Assert.Contains("ai_service_unavailable",text);Assert.DoesNotContain("stack",text,StringComparison.OrdinalIgnoreCase);}}
